final_sql:
SELECT COUNT(*) AS never_labelled_photos
FROM photos p
WHERE NOT EXISTS (SELECT 1 FROM labels l WHERE l.photo_id = p.photo_id);

SELECT COUNT(*) AS photos_with_no_tags
FROM photos
WHERE tags IS NULL OR len(list_filter(tags, x -> trim(x) <> '')) = 0;

select round(100.0 * avg(case when replace(p.legacy_tag_label, ' ', '_') = l.subject then 1 else 0 end), 1) as pct_agree, count(*) as n
from photos p join labels l using(photo_id)
where p.legacy_tag_label is not null and p.legacy_tag_label not in ('unclassified', 'observatory / engineering')
